import pytest

from durations import format_duration, parse_duration


def test_formats_hours_and_minutes():
    assert format_duration(5400) == "1h30m"


def test_formats_zero():
    assert format_duration(0) == "0s"


@pytest.mark.parametrize(
    "text, expected",
    [("1h30m", 5400), ("45s", 45), ("2h", 7200), ("5m", 300), ("1h2m3s", 3723), ("0s", 0)],
)
def test_parse_duration(text, expected):
    assert parse_duration(text) == expected


@pytest.mark.parametrize("text", ["", "   ", "10x", "abc", "1h 30m", "30m1h", "-5s", "1.5h", "h"])
def test_parse_duration_rejects_bad_text(text):
    with pytest.raises(ValueError):
        parse_duration(text)


def test_roundtrip():
    assert parse_duration(format_duration(5400)) == 5400

